(() => {
  'use strict';
  const canvas = document.querySelector('#world');
  const ctx = canvas.getContext('2d');
  const minimap = document.querySelector('#minimap');
  const mapCtx = minimap.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const WORLD = { w: 3400, h: 2700 };
  const state = {
    player: { x: 1610, y: 1450, vx: 0, vy: 0, facing: 1, health: 100, hunger: 82, thirst: 76, stamina: 100, temp: 22, moving: false, attacking: 0 },
    inventory: { wood: 0, stone: 0, berries: 1, fiber: 0, water: 1, iron: 0, meat: 0, hide: 0, campfire: 0, spear: 0, axe: 0, shelter: 0 },
    time: 7.7, day: 1, weather: 'CLEAR', selected: 0, activePanel: '', buildMode: '', paused: false, sound: true, dead: false,
    journal: [], mobs: [], buildings: [], collected: 0, lastSave: 0, toastTimer: 0, gameSeconds: 0, playerStep: 0, mobileX: 0, mobileY: 0
  };
  const saved = (() => { try { return JSON.parse(localStorage.getItem('wild-survival-save')); } catch { return null; } })();
  let seed = 81423;
  function srnd() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
  const objects = [];
  const patches = [];
  const types = ['tree','pine','rock','bush','berry','herb','log','iron'];
  function terrainAt(x, y) {
    const edge = Math.min(x, y, WORLD.w - x, WORLD.h - y);
    if (edge < 92) return 'water';
    if (edge < 156) return 'sand';
    const n = Math.sin(x * .002 + Math.sin(y * .0016)) + Math.cos(y * .0022 + Math.sin(x * .0014));
    if (x > 2480 && y > 1720 && y < 2250) return 'rocky';
    if (x < 1000 && y > 1450) return 'marsh';
    if (n > 1.08) return 'clearing';
    if (n < -.85) return 'pineforest';
    return 'forest';
  }
  for (let i=0;i<185;i++) {
    const x = rand(145,WORLD.w-145), y = rand(145,WORLD.h-145), biome = terrainAt(x,y);
    let type = types[Math.floor(rand(0,types.length))];
    if (biome === 'rocky') type = Math.random()<.58?'rock':'iron';
    if (biome === 'marsh') type = Math.random()<.55?'herb':'berry';
    if (biome === 'clearing') type = Math.random()<.42?'berry':(Math.random()<.5?'log':'herb');
    if (biome === 'pineforest') type = Math.random()<.75?'pine':'rock';
    objects.push({x,y,type,size:rand(.8,1.3),id:i,alive:true});
  }
  for(let i=0;i<95;i++) patches.push({x:rand(0,WORLD.w),y:rand(0,WORLD.h),r:rand(35,145),tone:rand(0,1)});
  for(let i=0;i<7;i++) state.mobs.push({x:rand(700,2600),y:rand(700,2100),type:i<5?'wolf':'crawler',hp:i<5?2:3,alive:true,alert:false,phase:rand(0,6)});
  const items = {
    wood:{name:'Wood',icon:'▰',desc:'Strong and versatile timber.'},stone:{name:'Stone',icon:'◈',desc:'A solid piece of island granite.'},berries:{name:'Wild berries',icon:'●',desc:'Sweet, tart, and just a little wild.'},fiber:{name:'Plant fiber',icon:'〽',desc:'Tough strands from island plants.'},water:{name:'Fresh water',icon:'◉',desc:'Clean water to keep you going.'},iron:{name:'Iron ore',icon:'⬟',desc:'A rare vein of raw iron.'},meat:{name:'Raw meat',icon:'◆',desc:'Best cooked over a fire.'},hide:{name:'Animal hide',icon:'▱',desc:'Useful for sturdy gear.'},campfire:{name:'Campfire',icon:'♨',desc:'Warmth, light, and a place to cook.'},spear:{name:'Wooden spear',icon:'↗',desc:'A reliable first line of defense.'},axe:{name:'Stone hatchet',icon:'⚒',desc:'Harvest trees more efficiently.'},shelter:{name:'Lean-to shelter',icon:'⌂',desc:'A safe place to rest through the night.'}
  };
  if(saved){
    Object.assign(state.player,saved.player||{}); Object.assign(state.inventory,saved.inventory||{});
    state.day=saved.day||1;state.time=saved.time||7.7;state.collected=saved.collected||0;
    state.buildings=saved.buildings||[];if(saved.objects) saved.objects.forEach(o=>{const found=objects.find(x=>x.id===o.id);if(found)found.alive=o.alive;});
    toast('Welcome back, survivor. Your progress is restored.');
  }
  function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  addEventListener('resize',resize);resize();
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
  function saveGame(){const data={player:state.player,inventory:state.inventory,day:state.day,time:state.time,collected:state.collected,buildings:state.buildings,objects:objects.map(o=>({id:o.id,alive:o.alive}))};try{localStorage.setItem('wild-survival-save',JSON.stringify(data));}catch{}const el=$('#save-indicator');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1500);}
  function colorFor(t){return ({water:'#416f70',sand:'#b6a175',rocky:'#72796b',marsh:'#566f53',clearing:'#617f4e',pineforest:'#385d3f',forest:'#4c7049'})[t]||'#4c7049';}
  function screen(x,y){return {x:x-state.player.x+innerWidth/2,y:y-state.player.y+innerHeight/2};}
  function drawTerrain(){
    const w=innerWidth,h=innerHeight;ctx.fillStyle='#426344';ctx.fillRect(0,0,w,h);
    const camL=state.player.x-w/2,camT=state.player.y-h/2;
    for(let y=Math.floor(camT/96)*96;y<camT+h+100;y+=96)for(let x=Math.floor(camL/96)*96;x<camL+w+100;x+=96){
      const p=screen(x+48,y+48),biome=terrainAt(x+48,y+48);ctx.fillStyle=colorFor(biome);ctx.fillRect(p.x-49,p.y-49,98,98);
      let hsh=Math.abs(Math.sin(x*12.9898+y*78.233)*43758.5453)%1;
      if(biome==='water'){ctx.fillStyle='rgba(151,207,190,.12)';ctx.beginPath();ctx.ellipse(p.x+((hsh*19)-9),p.y+((hsh*29)-14),30,4,Math.sin(hsh*8)*.07,0,Math.PI*2);ctx.fill();}
      else if(biome==='sand'){ctx.fillStyle='rgba(247,220,157,.15)';for(let j=0;j<3;j++){ctx.beginPath();ctx.arc(p.x+(hsh*60-30)+j*9,p.y+(hsh*35-18),1.2,0,7);ctx.fill();}}
      else {ctx.fillStyle=biome==='clearing'?'rgba(195,207,121,.19)':'rgba(190,210,140,.13)';for(let j=0;j<3;j++){const fx=p.x+(hsh*60-30)+Math.sin(j*4+hsh)*17,fy=p.y+(hsh*34-17)+Math.cos(j*2+hsh)*10;ctx.beginPath();ctx.ellipse(fx,fy,1.3,2.1,hsh,0,7);ctx.fill();}}
    }
    for(const patch of patches){const p=screen(patch.x,patch.y);if(p.x< -patch.r||p.x>innerWidth+patch.r||p.y< -patch.r||p.y>innerHeight+patch.r)continue;const b=terrainAt(patch.x,patch.y);if(['water','sand'].includes(b))continue;ctx.fillStyle=`rgba(${b==='clearing'?'183,195,112':'23,46,26'},${.025+patch.tone*.025})`;ctx.beginPath();ctx.ellipse(p.x,p.y,patch.r,patch.r*.53,patch.tone*3,0,Math.PI*2);ctx.fill();}
    // Island shoreline highlights
    ctx.save();ctx.translate(-camL,-camT);ctx.strokeStyle='rgba(226,213,164,.22)';ctx.lineWidth=7;ctx.strokeRect(96,96,WORLD.w-192,WORLD.h-192);ctx.restore();
  }
  function drawTree(o,p){const s=o.size;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='rgba(14,26,17,.32)';ctx.beginPath();ctx.ellipse(2,7,24,9,0,0,7);ctx.fill();ctx.fillStyle='#634b37';ctx.fillRect(-4,-18,8,27);ctx.fillStyle=o.type==='pine'?'#224b35':'#31583a';ctx.beginPath();ctx.ellipse(0,-29,24,29,0,0,7);ctx.fill();ctx.fillStyle=o.type==='pine'?'#2d6241':'#3e7047';ctx.beginPath();ctx.ellipse(-5,-36,18,23,-.25,0,7);ctx.fill();ctx.fillStyle='rgba(163,190,103,.17)';ctx.beginPath();ctx.ellipse(-10,-47,9,11,-.5,0,7);ctx.fill();ctx.restore();}
  function drawResource(o,p){const s=o.size;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='rgba(13,25,17,.3)';ctx.beginPath();ctx.ellipse(0,4,15,6,0,0,7);ctx.fill();
    if(o.type==='rock'||o.type==='iron'){ctx.fillStyle=o.type==='iron'?'#777b72':'#777d70';ctx.beginPath();ctx.moveTo(-14,1);ctx.lineTo(-10,-11);ctx.lineTo(-1,-18);ctx.lineTo(13,-13);ctx.lineTo(16,-1);ctx.lineTo(7,5);ctx.lineTo(-9,6);ctx.closePath();ctx.fill();ctx.fillStyle=o.type==='iron'?'#bd9863':'#abb3a0';ctx.beginPath();ctx.moveTo(-10,-11);ctx.lineTo(-1,-18);ctx.lineTo(13,-13);ctx.lineTo(2,-8);ctx.closePath();ctx.fill();if(o.type==='iron'){ctx.fillStyle='#e3ba73';ctx.fillRect(-3,-8,3,3);ctx.fillRect(6,-6,3,3);}}
    else if(o.type==='berry'||o.type==='bush'||o.type==='herb'){ctx.fillStyle=o.type==='herb'?'#66864b':'#426e45';ctx.beginPath();ctx.ellipse(-5,-5,9,8,0,0,7);ctx.ellipse(5,-7,8,8,0,0,7);ctx.ellipse(0,-11,8,8,0,0,7);ctx.fill();if(o.type==='berry'){ctx.fillStyle='#c75f68';for(const [x,y] of [[-5,-8],[4,-10],[1,-3],[-1,-14]]){ctx.beginPath();ctx.arc(x,y,2,0,7);ctx.fill();}}else if(o.type==='herb'){ctx.strokeStyle='#bac86d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-2,-15);ctx.moveTo(0,0);ctx.lineTo(6,-12);ctx.stroke();}}
    else {ctx.fillStyle='#725b3f';ctx.save();ctx.rotate(-.25);ctx.fillRect(-16,-4,32,8);ctx.fillStyle='#a18860';ctx.fillRect(-12,-4,9,2);ctx.restore();}
    ctx.restore();}
  function drawBuilding(b,p){if(b.type==='campfire'){const flick=Math.sin(performance.now()/90+b.x)*2;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='rgba(239,149,62,.13)';ctx.beginPath();ctx.arc(0,-7,31+flick,0,7);ctx.fill();ctx.fillStyle='#63452f';ctx.beginPath();ctx.ellipse(0,1,16,6,0,0,7);ctx.fill();ctx.strokeStyle='#a27445';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-10,1);ctx.lineTo(10,-5);ctx.moveTo(-9,-5);ctx.lineTo(9,1);ctx.stroke();ctx.fillStyle='#ffae4d';ctx.beginPath();ctx.moveTo(0,-3);ctx.quadraticCurveTo(-12,-15+flick,0,-29-flick);ctx.quadraticCurveTo(13,-14,0,-3);ctx.fill();ctx.fillStyle='#ffdf84';ctx.beginPath();ctx.moveTo(0,-4);ctx.quadraticCurveTo(-5,-13,1,-20);ctx.quadraticCurveTo(8,-11,0,-4);ctx.fill();ctx.restore();}else{ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='rgba(14,25,15,.3)';ctx.beginPath();ctx.ellipse(0,3,30,12,0,0,7);ctx.fill();ctx.fillStyle='#77583b';ctx.beginPath();ctx.moveTo(-24,0);ctx.lineTo(-20,-20);ctx.lineTo(0,-38);ctx.lineTo(20,-20);ctx.lineTo(24,0);ctx.closePath();ctx.fill();ctx.fillStyle='#b68752';ctx.beginPath();ctx.moveTo(-26,-20);ctx.lineTo(0,-45);ctx.lineTo(26,-20);ctx.lineTo(20,-17);ctx.lineTo(0,-36);ctx.lineTo(-20,-17);ctx.closePath();ctx.fill();ctx.restore();}}
  function drawMob(m,p,now){ctx.save();ctx.translate(p.x,p.y+Math.sin(now/260+m.phase)*2);const night=state.time>19||state.time<5;ctx.fillStyle='rgba(15,23,17,.3)';ctx.beginPath();ctx.ellipse(0,4,14,6,0,0,7);ctx.fill();if(m.type==='wolf'){ctx.fillStyle=m.alert?'#8f5a48':'#746a57';ctx.beginPath();ctx.ellipse(0,-5,14,8,-.05,0,7);ctx.fill();ctx.beginPath();ctx.arc(10,-11,7,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(5,-15);ctx.lineTo(4,-22);ctx.lineTo(10,-17);ctx.moveTo(13,-16);ctx.lineTo(18,-21);ctx.lineTo(17,-13);ctx.fill();ctx.strokeStyle='#c9a179';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-9,5);ctx.moveTo(4,0);ctx.lineTo(4,5);ctx.stroke();ctx.fillStyle='#e8cc8d';ctx.fillRect(12,-12,2,2);}else{ctx.fillStyle=night?'#554752':'#625c4e';ctx.beginPath();ctx.ellipse(0,-6,10,14,0,0,7);ctx.fill();ctx.fillStyle='#e38165';ctx.fillRect(4,-12,2,2);ctx.fillRect(8,-12,2,2);}ctx.restore();}
  function drawPlayer(now){const p=screen(state.player.x,state.player.y),step=state.moving?Math.sin(now/80)*2.5:0;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='rgba(11,24,17,.4)';ctx.beginPath();ctx.ellipse(0,5,12,7,0,0,7);ctx.fill();ctx.strokeStyle='#27342b';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-4,-3);ctx.lineTo(-5+step,-13);ctx.moveTo(4,-3);ctx.lineTo(5-step,-13);ctx.stroke();ctx.fillStyle='#d2c19a';ctx.beginPath();ctx.ellipse(0,-19,8,10,0,0,7);ctx.fill();ctx.fillStyle='#4d7252';ctx.beginPath();ctx.roundRect(-9,-31,18,18,5);ctx.fill();ctx.fillStyle='#b1a17f';ctx.beginPath();ctx.arc(0,-36,6,0,7);ctx.fill();ctx.fillStyle='#4f5139';ctx.beginPath();ctx.arc(-1,-38,7,Math.PI,0);ctx.fill();ctx.fillStyle='#d3b876';ctx.fillRect(state.player.facing>0?3:-5,-37,2,2);if(state.player.attacking>0){ctx.strokeStyle='rgba(228,236,192,.65)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(state.player.facing*14,-22,19,-1.2,.9);ctx.stroke();}ctx.restore();}
  function daylight(){return clamp((Math.sin((state.time-6)/24*Math.PI*2)+.32)/1.1,0,1);}
  function render(){const now=performance.now();drawTerrain();const vis=objects.filter(o=>o.alive&&Math.abs(o.x-state.player.x)<innerWidth*.7&&Math.abs(o.y-state.player.y)<innerHeight*.7).map(o=>({obj:o,p:screen(o.x,o.y)}));const drawables=[...vis.map(x=>({y:x.obj.y,type:'object',...x})),...state.buildings.map(b=>({y:b.y,type:'building',obj:b,p:screen(b.x,b.y)})),...state.mobs.filter(m=>m.alive&&Math.abs(m.x-state.player.x)<innerWidth&&Math.abs(m.y-state.player.y)<innerHeight).map(m=>({y:m.y,type:'mob',obj:m,p:screen(m.x,m.y)})),{y:state.player.y,type:'player'}].sort((a,b)=>a.y-b.y);
    for(const d of drawables){if(d.type==='object'){if(['tree','pine'].includes(d.obj.type))drawTree(d.obj,d.p);else drawResource(d.obj,d.p);}else if(d.type==='building')drawBuilding(d.obj,d.p);else if(d.type==='mob')drawMob(d.obj,d.p,now);else drawPlayer(now);}
    const light=daylight();ctx.fillStyle=`rgba(15,25,51,${.48*(1-light)})`;ctx.fillRect(0,0,innerWidth,innerHeight);
    if(state.weather==='RAIN'){ctx.strokeStyle='rgba(189,215,223,.35)';ctx.lineWidth=1;for(let i=0;i<80;i++){const x=(i*127+now*.36)%innerWidth,y=(i*73+now*.8)%innerHeight;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+10);ctx.stroke();}}
    if(state.weather==='FOG'){const fog=ctx.createRadialGradient(innerWidth*.52,innerHeight*.4,30,innerWidth*.52,innerHeight*.4,innerWidth*.7);fog.addColorStop(0,'rgba(190,201,181,.02)');fog.addColorStop(1,'rgba(198,207,190,.24)');ctx.fillStyle=fog;ctx.fillRect(0,0,innerWidth,innerHeight);}
    drawMinimap();
  }
  function drawMinimap(target=mapCtx,w=minimap.width,h=minimap.height,large=false){target.clearRect(0,0,w,h);target.fillStyle='#486344';target.fillRect(0,0,w,h);const sx=w/WORLD.w,sy=h/WORLD.h;
    for(const p of patches){target.fillStyle=p.tone>.5?'rgba(28,57,38,.44)':'rgba(194,197,126,.23)';target.beginPath();target.arc(p.x*sx,p.y*sy,Math.max(1,p.r*sx),0,7);target.fill();}
    // river, trail, coastline
    target.strokeStyle='rgba(108,167,160,.8)';target.lineWidth=large?15:5;target.beginPath();target.moveTo(w*.44,0);target.bezierCurveTo(w*.54,h*.22,w*.33,h*.42,w*.5,h*.62);target.bezierCurveTo(w*.66,h*.78,w*.44,h*.9,w*.53,h);target.stroke();
    target.strokeStyle='rgba(208,188,135,.62)';target.lineWidth=large?4:1.5;target.beginPath();target.moveTo(w*.18,h*.78);target.quadraticCurveTo(w*.45,h*.64,w*.78,h*.83);target.stroke();
    target.fillStyle='#e5c27a';target.beginPath();target.arc(state.player.x*sx,state.player.y*sy,large?7:3.2,0,7);target.fill();target.strokeStyle='rgba(244,221,160,.7)';target.lineWidth=1;target.beginPath();target.arc(state.player.x*sx,state.player.y*sy,large?15:7,0,7);target.stroke();
    for(const m of state.mobs.filter(x=>x.alive)){target.fillStyle='#ed8a70';target.fillRect(m.x*sx-1.5,m.y*sy-1.5,large?6:3,large?6:3);}
    for(const b of state.buildings){target.fillStyle=b.type==='campfire'?'#ffc36f':'#e5e9c3';target.fillRect(b.x*sx-2,b.y*sy-2,large?6:3,large?6:3);}
  }
  function nearestObject(){let best=null,bd=80;for(const o of objects){if(!o.alive)continue;const d=dist(o,state.player);if(d<bd){bd=d;best=o;}}return best;}
  function nearestMob(){let best=null,bd=65;for(const m of state.mobs){if(m.alive&&dist(m,state.player)<bd){best=m;bd=dist(m,state.player);}}return best;}
  function updateHint(){const o=nearestObject(),m=nearestMob(),hint=$('#interaction-hint');if(m){$('#nearby-name').textContent=m.type==='wolf'?'Wild wolf':'Night crawler';hint.classList.add('show');hint.querySelector('kbd').textContent='F';}else if(o){$('#nearby-name').textContent=({tree:'Pine tree',pine:'Pine tree',rock:'Granite',bush:'Wild greens',berry:'Berry bush',herb:'Medicinal herbs',log:'Driftwood',iron:'Iron vein'})[o.type];hint.classList.add('show');hint.querySelector('kbd').textContent='E';}else if(state.player.x<1000&&state.player.y>1450){$('#nearby-name').textContent='Fresh water';hint.classList.add('show');hint.querySelector('kbd').textContent='E';}else hint.classList.remove('show');}
  function addItem(key,n=1){state.inventory[key]=(state.inventory[key]||0)+n;state.collected+=n;toast(`+${n} ${items[key]?.name||key}`);updateUI();}
  function interact(){if(state.dead)return;const o=nearestObject();if(o){o.alive=false;const loot={tree:['wood',2],pine:['wood',2],rock:['stone',1],bush:['fiber',1],berry:['berries',2],herb:['fiber',2],log:['wood',1],iron:['iron',1]}[o.type];addItem(loot[0],loot[1]);if(o.type==='berry'&&Math.random()<.4)addItem('berries',1);checkQuest();return;}if(state.player.x<1000&&state.player.y>1450){if(state.inventory.water<5)addItem('water');else toast('Your water pouch is full.');return;}toast('Nothing within reach. Explore the island to find supplies.');}
  function attack(){if(state.player.stamina<7){toast('Too exhausted to attack.');return;}state.player.stamina-=7;state.player.attacking=.25;let m=nearestMob();if(!m){m=state.mobs.filter(x=>x.alive).sort((a,b)=>dist(a,state.player)-dist(b,state.player))[0];if(m&&dist(m,state.player)<105){state.player.facing=m.x>state.player.x?1:-1;}}
    if(m&&dist(m,state.player)<105){m.hp-=state.inventory.spear?2:1;m.alert=true;const d=dist(m,state.player)||1;m.x+=(m.x-state.player.x)/d*28;m.y+=(m.y-state.player.y)/d*28;if(m.hp<=0){m.alive=false;addItem('meat',1);addItem('hide',1);toast('The island provides. You gathered meat and hide.');}else toast(m.type==='wolf'?'The wolf recoils!':'You struck the creature!');}else toast('No danger in striking distance.');updateUI();}
  function checkQuest(){const wood=state.inventory.wood>=4,stone=state.inventory.stone>=2,fire=state.inventory.campfire>0;[['task-wood',wood],['task-stone',stone],['task-fire',fire]].forEach(([id,ok])=>$( `#${id}`).classList.toggle('done',ok));$('#task-wood-count').textContent=`${Math.min(4,state.inventory.wood)} / 4`;
    $('#task-stone-count').textContent=`${Math.min(2,state.inventory.stone)} / 2`;const n=Number(wood)+Number(stone)+Number(fire);$('#quest-count').textContent=`${n} / 3`;$('#quest-progress').style.width=`${n/3*100}%`;if(n===3&&!state.journal.includes('first-night')){state.journal.push('first-night');toast('Quest complete — the first night is yours.');}}
  function updateUI(){for(const key of ['health','hunger','thirst','stamina']){$(`#${key}-fill`).style.width=`${clamp(state.player[key],0,100)}%`;$(`#${key}-value`).textContent=Math.round(state.player[key]);}
    $('#temperature').textContent=`${Math.round(state.player.temp)}°`;$('#day-number').textContent=String(state.day).padStart(2,'0');const hh=Math.floor(state.time)%24,mm=Math.floor((state.time%1)*60);$('#time-label').textContent=`${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}`;$('#clock').innerHTML=`${String(hh%12||12).padStart(2,'0')}:${String(mm).padStart(2,'0')} <i>${hh>=12?'PM':'AM'}</i>`;$('#day-progress').style.width=`${state.time/24*100}%`;$('#sun-mark').textContent=state.time>19||state.time<5?'☾':'☼';$('#weather-line').textContent=`${state.weather==='CLEAR'?'CLEAR SKIES':state.weather} · ${Math.round(state.player.temp)}°C`;$('#coords').textContent=`${Math.round(state.player.x/10)}, ${Math.round(state.player.y/10)}`;
    $('#condition-title').textContent=state.time>19||state.time<5?'Night is falling':'A fresh start';$('#condition-copy').textContent=state.player.hunger<25?'You need to find something to eat.':state.player.thirst<25?'Find fresh water soon.':'Gather what you can before nightfall.';renderHotbar();checkQuest();}
  function renderHotbar(){const keys=['spear','berries','water','campfire','axe'];$('#hotbar-slots').innerHTML=keys.map((k,i)=>`<button class="slot ${state.selected===i?'selected':''}" data-slot="${i}" title="${items[k].name}"><em>${i+1}</em>${items[k].icon}<b>${state.inventory[k]||0}</b></button>`).join('');document.querySelectorAll('.slot').forEach(el=>el.onclick=()=>useSlot(Number(el.dataset.slot)));}
  function useSlot(i){state.selected=i;if(i===1){if(state.inventory.berries>0){state.inventory.berries--;state.player.hunger=clamp(state.player.hunger+24,0,100);toast('You ate a handful of wild berries.');}else toast('No berries in your pack.');}else if(i===2){if(state.inventory.water>0){state.inventory.water--;state.player.thirst=clamp(state.player.thirst+35,0,100);toast('Fresh water. That feels better.');}else toast('No fresh water in your pack.');}else if(i===3){if(state.inventory.campfire)startBuild('campfire');else toast('Craft a campfire first.');}else if(i===0&&state.inventory.spear===0)toast('Craft a spear to improve your defense.');else if(i===4&&state.inventory.axe===0)toast('A hatchet will make gathering easier.');updateUI();}
  const recipes=[{key:'campfire',name:'Campfire',icon:'♨',cost:{wood:3,stone:2},category:'Survival'},{key:'spear',name:'Wooden spear',icon:'↗',cost:{wood:2,fiber:1},category:'Weapons'},{key:'axe',name:'Stone hatchet',icon:'⚒',cost:{wood:2,stone:2},category:'Tools'},{key:'shelter',name:'Lean-to shelter',icon:'⌂',cost:{wood:6,fiber:3},category:'Building'}];
  function canCraft(r){return Object.entries(r.cost).every(([k,n])=>state.inventory[k]>=n);}
  function craft(key){const r=recipes.find(x=>x.key===key);if(!r||!canCraft(r)){toast('You need more materials for that.');return;}for(const [k,n] of Object.entries(r.cost))state.inventory[k]-=n;state.inventory[key]++;toast(`Crafted ${r.name}.`);updateUI();if(key==='campfire')checkQuest();}
  function startBuild(type){if(!state.inventory[type]){toast(`Craft a ${items[type]?.name||type} first.`);return;}state.buildMode=type;closePanel();toast(`Tap or click the ground to place your ${items[type].name.toLowerCase()}.`);}
  canvas.addEventListener('pointerdown',e=>{if(state.buildMode){const rect=canvas.getBoundingClientRect(),x=state.player.x+e.clientX-rect.width/2,y=state.player.y+e.clientY-rect.height/2;if(terrainAt(x,y)==='water'){toast('That spot is under water. Choose solid ground.');return;}state.buildings.push({x,y,type:state.buildMode});state.inventory[state.buildMode]--;state.buildMode='';toast('Built! Your island is starting to feel like home.');checkQuest();updateUI();}});
  function panel(title,subtitle,body,eyebrow='SURVIVOR KIT'){ $('#panel-content').innerHTML=`<div class="panel-eyebrow">${eyebrow}</div><h1 class="panel-title">${title}</h1><p class="panel-subtitle">${subtitle}</p>${body}`;$('#panel-overlay').classList.add('open');state.activePanel=title;state.paused=true;}
  function closePanel(){$('#panel-overlay').classList.remove('open');state.activePanel='';state.paused=false;state.buildMode='';}
  function openInventory(){const body=`<div class="inventory-grid">${Object.entries(state.inventory).filter(([,n])=>n>0).map(([k,n])=>`<div class="item-card"><span class="item-emoji">${items[k].icon}</span><span class="quantity">×${n}</span><b>${items[k].name}</b><small>${items[k].desc}</small></div>`).join('')||'<p class="panel-subtitle">Your pack is empty. Explore nearby for supplies.</p>'}</div><div class="section-heading">SURVIVAL TIP <span>✦</span></div><p class="panel-subtitle">Keep your hunger and thirst above zero. Eating berries restores hunger; fresh water restores thirst.</p>`;panel('Your inventory','Everything you have gathered on the island.',body);}
  function openCraft(){const body=`<div class="panel-tabs"><button class="active" data-filter="All">ALL</button><button data-filter="Survival">SURVIVAL</button><button data-filter="Weapons">WEAPONS</button><button data-filter="Tools">TOOLS</button><button data-filter="Building">BUILDING</button></div><div class="recipe-list">${recipes.map(r=>`<div class="recipe" data-category="${r.category}"><span class="recipe-icon">${r.icon}</span><div class="recipe-info"><b>${r.name}</b><small>${Object.entries(r.cost).map(([k,n])=>`${items[k].name} ×${n} (${state.inventory[k]||0})`).join(' · ')}</small></div><button data-craft="${r.key}" ${canCraft(r)?'':'disabled'}>CRAFT</button></div>`).join('')}</div>`;panel('Craft & create','Turn what you find into the tools you need to survive.',body,'WORKBENCH');document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{craft(b.dataset.craft);openCraft();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.recipe').forEach(r=>r.style.display=b.dataset.filter==='All'||r.dataset.category===b.dataset.filter?'flex':'none');});}
  function openBuild(){const body=`<p class="panel-subtitle">Choose a structure, then tap or click a spot on the island to place it.</p><div class="recipe-list">${recipes.filter(r=>r.category==='Building'||r.key==='campfire').map(r=>`<div class="recipe"><span class="recipe-icon">${r.icon}</span><div class="recipe-info"><b>${items[r.key].name}</b><small>In pack: ${state.inventory[r.key]||0}</small></div><button data-place="${r.key}" ${state.inventory[r.key]?'':'disabled'}>PLACE</button></div>`).join('')}</div><div class="section-heading">BUILDING GUIDE</div><p class="panel-subtitle">Place campfires anywhere for warmth and light. Shelters make a perfect base camp — and you can build as many as you have materials for.</p>`;panel('Build your base','Create a safe haven on this wild island.',body,'BASE CAMP');document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>startBuild(b.dataset.place));}

