  function openMap(){const body=`<canvas class="map-large" id="large-map" width="920" height="590"></canvas><div class="map-legend"><span>You are here</span><span>Wildlife</span><span>Camp & shelter</span></div><div class="section-heading">KNOWN LANDMARKS</div><div class="journal-entry">Whispering Pines <small>Dense woodland · timber and wild berries</small></div><div class="journal-entry">Old Riverbend <small>Fresh water source · west of the forest</small></div><div class="journal-entry">Shattered Ridge <small>Rocky uplands · stone and iron</small></div>`;panel('The island','A little knowledge makes a big difference.',body,'FIELD MAP');drawMinimap($('#large-map').getContext('2d'),920,590,true);}
  function openJournal(){const body=`<div class="journal-entry">Make this island your own.<small>Gather 4 wood, 2 stone, then craft a campfire. Progress: ${Math.min(state.inventory.wood,4)}/4 wood · ${Math.min(state.inventory.stone,2)}/2 stone · ${state.inventory.campfire?'Campfire ready':'No campfire yet'}.</small></div><div class="journal-entry">Explore the shoreline.<small>Look for driftwood and fresh water near the edge of the island.</small></div><div class="journal-entry">Stay alert after dark.<small>Wildlife becomes more active when night falls. A spear can keep you safe.</small></div><div class="section-heading">DISCOVERIES · ${state.journal.length}</div><p class="panel-subtitle">${state.journal.length?'Your campfire marks the beginning of a new chapter.':'The island is full of secrets. Your discoveries will be recorded here.'}</p>`;panel('Survivor journal','Notes, discoveries, and the story you are writing.',body,'FIELD NOTES');}
  function movePlayer(dx,dy,dt){const p=state.player,mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}const sprint=(keys.has('Shift')||state.mobileSprint)&&p.stamina>2;let speed=sprint?238:164;if(sprint){p.stamina=Math.max(0,p.stamina-dt*18);}else p.stamina=Math.min(100,p.stamina+dt*11);if(Math.abs(dx)>.01)p.facing=dx>0?1:-1;
    p.vx+=(dx*speed-p.vx)*Math.min(1,dt*10);p.vy+=(dy*speed-p.vy)*Math.min(1,dt*10);p.moving=Math.abs(p.vx)+Math.abs(p.vy)>12;let nx=clamp(p.x+p.vx*dt,105,WORLD.w-105),ny=clamp(p.y+p.vy*dt,105,WORLD.h-105);
    // Trees and rocks have simple, forgiving collision boundaries.
    for(const o of objects){if(!o.alive||!['tree','pine','rock','iron'].includes(o.type))continue;const d=Math.hypot(nx-o.x,ny-o.y),r=o.type==='rock'||o.type==='iron'?17:24;if(d<r){const a=Math.atan2(ny-o.y,nx-o.x);nx=o.x+Math.cos(a)*r;ny=o.y+Math.sin(a)*r;}}
    p.x=nx;p.y=ny;}
  const keys=new Set();let stateMobileSprint=false;
  function tick(dt){if(state.paused||state.dead)return;state.gameSeconds+=dt;state.time+=dt*.05;if(state.time>=24){state.time-=24;state.day++;toast(`Day ${state.day}. The island is still yours to discover.`);}
    if(Math.floor(state.gameSeconds)%180===0&&Math.floor(state.gameSeconds)!==state.lastWeather){state.lastWeather=Math.floor(state.gameSeconds);state.weather=['CLEAR','CLEAR','RAIN','FOG'][Math.floor(Math.random()*4)];if(state.weather!=='CLEAR')toast(`${state.weather==='RAIN'?'Rain is moving in.':'A mist is settling over the island.'}`);}
    const dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0)+state.mobileX,dy=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0)+state.mobileY;movePlayer(dx,dy,dt);
    if(Math.floor(state.gameSeconds/18)>Math.floor((state.gameSeconds-dt)/18)){state.player.hunger=Math.max(0,state.player.hunger-.75);state.player.thirst=Math.max(0,state.player.thirst-1.05);if(state.player.hunger<1||state.player.thirst<1)state.player.health=Math.max(0,state.player.health-2);}
    const cold=state.time>21||state.time<5;state.player.temp+=(cold?-1:1)*dt*.12+(state.buildings.some(b=>b.type==='campfire'&&dist(b,state.player)<140)?dt*.42:0);state.player.temp=clamp(state.player.temp,8,31);
    const night=state.time>19||state.time<5;for(const m of state.mobs){if(!m.alive)continue;m.phase+=dt*2;const d=dist(m,state.player);m.alert=night&&d<270;if(m.alert){const dx=(state.player.x-m.x)/(d||1),dy=(state.player.y-m.y)/(d||1);m.x+=dx*dt*(m.type==='wolf'?43:30);m.y+=dy*dt*(m.type==='wolf'?43:30);if(d<25&&state.gameSeconds-(m.lastHit||0)>1.5){m.lastHit=state.gameSeconds;state.player.health=Math.max(0,state.player.health-(m.type==='wolf'?7:5));$('#damage-flash').classList.add('active');setTimeout(()=>$('#damage-flash').classList.remove('active'),170);toast('You are under attack!');}}else{m.x+=Math.sin(m.phase*.34)*dt*7;m.y+=Math.cos(m.phase*.29)*dt*7;}}
    if(state.player.health<=0){state.dead=true;showDeath();}state.player.attacking=Math.max(0,state.player.attacking-dt);if(state.gameSeconds-state.lastSave>35){state.lastSave=state.gameSeconds;saveGame();}if(Math.floor(state.gameSeconds*2)!==Math.floor((state.gameSeconds-dt)*2))updateUI();updateHint();}
  function showDeath(){panel('Lost in the wild','The island has won this round. You can try again from your last save.',`<p class="panel-subtitle">Your belongings remain where you left them. Rest up, then head back out.</p><button class="primary-btn" id="respawn">RETURN TO THE ISLAND</button>`,'SURVIVOR DOWN');$('#respawn').onclick=()=>{state.player.health=65;state.player.x=1610;state.player.y=1450;state.dead=false;closePanel();toast('Take a breath. You have another chance.');};}
  function bind(){
    $('#interact-btn').onclick=interact;$('#attack-btn').onclick=attack;$('#craft-btn').onclick=openCraft;$('#inventory-btn').onclick=openInventory;$('#build-btn').onclick=openBuild;$('#close-panel').onclick=closePanel;$('#panel-overlay').addEventListener('pointerdown',e=>{if(e.target.id==='panel-overlay')closePanel();});$('#map-toggle').onclick=openMap;$('#expand-map').onclick=openMap;$('#quest-journal').onclick=openJournal;$('#save-btn').onclick=()=>{saveGame();toast('Your progress is safe.');};$('#sound-toggle').onclick=()=>{state.sound=!state.sound;$('#sound-toggle').style.color=state.sound?'var(--lime)':'';toast(state.sound?'Ambient sound enabled.':'Ambient sound muted.');};
    addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(e.key==='Shift'?'Shift':k);if(e.repeat)return;if(k==='e')interact();if(k==='f'||k===' ')attack();if(k==='c')openCraft();if(k==='i')openInventory();if(k==='b')openBuild();if(k==='m')openMap();if(k==='escape')closePanel();if(k>='1'&&k<='5')useSlot(Number(k)-1);});addEventListener('keyup',e=>keys.delete(e.key==='Shift'?'Shift':e.key.toLowerCase()));
    $('#mobile-attack').onclick=attack;$('#mobile-use').onclick=interact;$('#mobile-jump').onclick=()=>{if(state.player.stamina>15){state.player.stamina-=15;state.player.vy-=170;toast('Quick step!');}};
    const joy=$('#joystick'),knob=$('#joy-knob');let joyPointer=null;joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(joyPointer);joyMove(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e);});function joyMove(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=29,d=Math.max(1,Math.hypot(dx,dy)),x=dx/d*Math.min(lim,d),y=dy/d*Math.min(lim,d);knob.style.transform=`translate(${x}px,${y}px)`;state.mobileX=x/lim;state.mobileY=y/lim;}function joyEnd(e){if(e.pointerId!==joyPointer)return;joyPointer=null;state.mobileX=state.mobileY=0;knob.style.transform='';}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);
    document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame();});window.addEventListener('beforeunload',saveGame);
  }
  let last=performance.now(),uiClock=0;function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;tick(dt);render();requestAnimationFrame(frame);}
  bind();updateUI();checkQuest();requestAnimationFrame(frame);
})();

